def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # DP arrays
    NEG_INF = -10**15
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps t = x + y
    for t in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        x_min = max(1, t - N)
        x_max = min(N, t - 1)
        for x1 in range(x_min, x_max + 1):
            y1 = t - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(x_min, x_max + 1):
                y2 = t - x2
                if y2 < 1 or y2 > N:
                    continue
                best = NEG_INF
                for dx1 in (0, 1):
                    prev_x1 = x1 - dx1
                    if prev_x1 < 1:
                        continue
                    for dx2 in (0, 1):
                        prev_x2 = x2 - dx2
                        if prev_x2 < 1:
                            continue
                        val = dp_prev[prev_x1][prev_x2]
                        if val > best:
                            best = val
                if best == NEG_INF:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                dp_cur[x1][x2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N] if N > 0 else 0

